fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let c: i32 = 40 + (t % 60) * 3;
    host::display::clear(0x000000);
    host::display::fill_rect(0, 0, w, 24, c * 65536);
    host::display::fill_rect(0, h - 24, w, 24, c * 65536);
    host::display::fill_rect(0, 0, 24, h, c * 65536);
    host::display::fill_rect(w - 24, 0, 24, h, c * 65536);
    host::display::draw_string(36, 36, "MIRROR", 0xffffff, 2);
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, host::compose::spawn_module("mirror", w / 4, h / 4, w / 2, h / 2));
    }
    let hdl: i32 = host::display::state_get(1);
    if hdl < 0 {
        host::display::draw_string(36, h - 48, "DEPTH CAP REACHED", 0xffff00, 1);
    } else {
        let st: i32 = host::compose::status(hdl);
        if st == 0 { host::display::draw_string(36, h - 48, "NESTING...", 0x808080, 1); }
        if st == 2 { host::display::draw_string(36, h - 48, "CHILD REFUSED", 0xff0000, 1); }
    }
    host::display::present();
}
